// Turns templates/<name>/** into lib/src/create/templates.g.dart, so the
// templates are inside the package's code: `just game init` writes them
// without reading files from its own package folder.
//
//     dart run tool/bundle_templates.dart
//
// The test "the bundled templates are the files in templates/"
// (test/templates_test.dart) fails when the generated file is out of date.
// The output is already as `dart format` writes it.
//
// A template's Dart files are kept as `<name>.dart.tmpl`: with their
// {{placeholders}} they aren't Dart yet, and the formatter and the analyzer
// (and pub.dev's score) would read them as broken code. The `.tmpl` is
// dropped here, so the bundle holds `lib/main.dart`.

import 'dart:convert';
import 'dart:io';

void main() {
  final out = File('lib/src/create/templates.g.dart');
  out.writeAsStringSync(bundle(Directory('templates')));
  stdout.writeln('Wrote ${out.path}.');
}

/// The generated library for every template folder under [root].
String bundle(Directory root) {
  final templates = <String, Map<String, String>>{};
  final dirs = root.listSync().whereType<Directory>().toList()
    ..sort((a, b) => a.path.compareTo(b.path));
  for (final dir in dirs) {
    final name = dir.uri.pathSegments.where((s) => s.isNotEmpty).last;
    final base = dir.absolute.path.replaceAll(r'\', '/');
    final files = <String, String>{};
    for (final f in dir.listSync(recursive: true).whereType<File>()) {
      var rel = f.absolute.path
          .replaceAll(r'\', '/')
          .substring(base.length + 1);
      if (rel.endsWith('.tmpl')) rel = rel.substring(0, rel.length - 5);
      files[rel] = f.readAsStringSync().replaceAll('\r\n', '\n');
    }
    templates[name] = {
      for (final key in files.keys.toList()..sort()) key: files[key]!,
    };
  }
  final b = StringBuffer()
    ..writeln('// GENERATED by tool/bundle_templates.dart from templates/.')
    ..writeln('// Do not edit: change the files there and run the tool.')
    ..writeln()
    ..writeln(
      '/// The templates `just game init` writes, by name: path → text.',
    )
    ..writeln('const Map<String, Map<String, String>> bundledTemplates = {');
  for (final t in templates.entries) {
    b.writeln('  ${_literal(t.key)}: {');
    for (final f in t.value.entries) {
      b.writeln(_entry(_literal(f.key), _literal(f.value)));
    }
    b.writeln('  },');
  }
  b.writeln('};');
  return '$b';
}

// A map entry the way `dart format` lays it out: on one line when it fits
// in 80 columns, otherwise the value on its own line below the key.
String _entry(String key, String value) {
  final line = '    $key: $value,';
  return line.length <= 80 ? line : '    $key:\n        $value,';
}

// A JSON string is a Dart string, but for `$`.
String _literal(String s) => jsonEncode(s).replaceAll(r'$', r'\$');
